import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const gradientT = smoothstep(0.08, 0.92, uv().y);
  backdropMaterial.colorNode = vec3(
    mix(vec3(new Color(colors.surface)), vec3(new Color(colors.ink)), gradientT)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(5.4, 2.55);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.55,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.12, -0.32);
  shadow.scale.set(1.02, 0.92, 1);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGeometry = new PlaneGeometry(5.1, 2.45);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.98
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = -0.08;
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const accentGeometry = new BoxGeometry(3.9, 0.035, 0.045);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-0.1, -0.78, 0.04);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const cornerGeometry = new BoxGeometry(0.28, 0.28, 0.035);
  const cornerMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const corner = new Mesh(cornerGeometry, cornerMaterial);
  corner.position.set(-2.15, 0.86, 0.04);
  root.add(corner);
  resources.push(cornerGeometry, cornerMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(-1.95, 0.05, 0.08);
    root.add(textObject);
  }

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      if (object.userData?.cleanup && object !== root) {
        object.userData.cleanup();
      }
    });

    root.clear();
  };

  return root;
}
